<script setup lang="ts">
import { computed,onMounted,ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessageBox,ElMessage } from 'element-plus'
import { api,ApiError,errorText } from '../api'
import { date,display,listItems,roles } from '../domain'
import type { Row } from '../domain'
import { useAuth } from '../stores/auth'
import { useLoad } from '../composables'
import PageState from '../components/PageState.vue'
const route=useRoute(),auth=useAuth(),items=ref<Row[]>([]),total=ref(0),page=ref(1),keyword=ref(''),drawer=ref(false),form=ref<Row>({}),busy=ref(false),formError=ref(''),operationError=ref(''),companies=ref<Row[]>([]),departments=ref<Row[]>([]),{loading,error,run}=useLoad()
const reauthRequired=ref(false),reauthCode=ref(''),reauthError=ref(''),reauthBusy=ref(false)
function clearReauth(){reauthRequired.value=false;reauthCode.value='';reauthError.value=''}
async function reauthenticate(){if(reauthBusy.value)return;reauthError.value='';if(!/^\d{6}$/.test(reauthCode.value)){reauthError.value='请输入六位动态验证码';return}reauthBusy.value=true;try{await api.post('/auth/totp/verify',{code:reauthCode.value});clearReauth();formError.value='';ElMessage.success('验证成功，请重新保存配置')}catch(e){reauthCode.value='';reauthError.value=errorText(e)}finally{reauthBusy.value=false}}
type Field={key:string;label:string;type?:string;required?:boolean;options?:Record<string,string>}
const schemas:Record<string,{title:string;subtitle:string;fields:Field[]}>= {
 companies:{title:'公司管理',subtitle:'维护公司主体与组织状态，保留历史责任关系。',fields:[{key:'code',label:'公司编码',required:true},{key:'name',label:'公司名称',required:true},{key:'enabled',label:'启用',type:'boolean'}]},
 departments:{title:'部门管理',subtitle:'按公司维护职能部门，明确协作和任务责任归属。',fields:[{key:'companyId',label:'所属公司',type:'company',required:true},{key:'code',label:'部门编码',required:true},{key:'name',label:'部门名称',required:true},{key:'enabled',label:'启用',type:'boolean'}]},
 users:{title:'用户与岗位',subtitle:'账号与岗位范围分别维护，跨公司任职按当前上下文授权。',fields:[{key:'account',label:'工号',required:true},{key:'name',label:'姓名',required:true},{key:'password',label:'初始 / 重置密码（留空不修改）',type:'password'},{key:'enabled',label:'启用账号',type:'boolean'},{key:'mustChangePassword',label:'下次登录必须改密',type:'boolean'}]},
 tags:{title:'职能标签',subtitle:'为任务职能匹配提供可解释的词条与部门关联。',fields:[{key:'name',label:'标签名称',required:true},{key:'deptId',label:'关联部门',type:'department',required:true},{key:'keywords',label:'命中关键词（逗号分隔）',type:'textarea'},{key:'negativeKeywords',label:'否定关键词（逗号分隔）',type:'textarea'},{key:'weight',label:'匹配权重',type:'number'},{key:'enabled',label:'启用',type:'boolean'}]},
 rules:{title:'匹配规则',subtitle:'规则版本用于说明分配依据，建议结果由领导确认。',fields:[{key:'name',label:'规则名称',required:true},{key:'deptId',label:'建议部门',type:'department',required:true},{key:'keywords',label:'命中关键词（逗号分隔）',type:'textarea',required:true},{key:'negativeKeywords',label:'否定关键词（逗号分隔）',type:'textarea'},{key:'role',label:'建议职责',type:'select',options:{HOST:'主办',COLLABORATOR:'协办'}},{key:'weight',label:'权重',type:'number'},{key:'priority',label:'规则优先级',type:'number'},{key:'enabled',label:'启用',type:'boolean'}]},
 'notification-channels':{title:'通知渠道',subtitle:'管理站内与企业通知投递渠道，敏感凭据仅用于写入。',fields:[{key:'name',label:'渠道名称',required:true},{key:'type',label:'渠道类型',type:'select',options:{IN_APP:'站内通知',WECOM:'企业微信',WEBHOOK:'Webhook'}},{key:'companyId',label:'所属公司',type:'company'},{key:'endpoint',label:'HTTPS投递地址',type:'url'},{key:'secret',label:'签名密钥（留空不修改）',type:'password'},{key:'enabled',label:'启用',type:'boolean'}]},
 'audit-logs':{title:'操作日志',subtitle:'按授权查看变更留痕与操作追踪，不展示认证凭据。',fields:[]}
}
const resource=computed(()=>String(route.params.resource)),schema=computed(()=>schemas[resource.value]),readOnly=computed(()=>resource.value==='audit-logs'),columns=computed(()=>{if(readOnly.value)return [{key:'createdAt',label:'操作时间'},{key:'actorId',label:'操作人ID'},{key:'action',label:'动作'},{key:'companyId',label:'公司ID'},{key:'objectId',label:'对象编号'},{key:'traceId',label:'追踪号'}];return schema.value?.fields.filter(f=>!['password','secret','textarea'].includes(f.type??'')).slice(0,5)??[]})
function load(){if(auth.me?.role!=='ADMIN'&&!(readOnly.value&&['GROUP_LEADER','DIVISION_LEADER','COMPANY_LEADER'].includes(auth.me?.role??''))){error.value='您没有管理配置权限';return}if(!schema.value){error.value='该管理页面不存在';return}run(()=>api.get(readOnly.value?'/audit':`/admin/${resource.value}`,{page:page.value,pageSize:20,keyword:keyword.value||undefined}),v=>{items.value=listItems(v);total.value=v.total??items.value.length})}
async function options(){try{const result=await Promise.all([api.get('/admin/companies'),api.get('/organization/departments')]);companies.value=listItems(result[0]);departments.value=listItems(result[1])}catch(e){operationError.value=errorText(e)}}
function edit(row?:Row){clearReauth();formError.value='';const f:Row={enabled:true,weight:1,priority:0,role:'HOST',type:'IN_APP',companyId:auth.me?.companyId,mustChangePassword:true};if(row){for(const field of schema.value.fields){if(!['password','secret'].includes(field.type??''))f[field.key]=Array.isArray(row[field.key])?row[field.key].join(','):row[field.key]}f.id=row.id;f.version=row.version;f.scopes=JSON.parse(JSON.stringify(row.scopes??[]))}else if(resource.value==='users')f.scopes=[];form.value=f;drawer.value=true}
function addScope(){form.value.scopes.push({role:'EMPLOYEE',companyId:auth.me?.companyId,deptId:'',enabled:true})}
async function save(){formError.value='';for(const f of schema.value.fields){if(f.required&&(form.value[f.key]==null||String(form.value[f.key]).trim()==='')){formError.value=`请填写${f.label}`;return}}if(resource.value==='users'&&!form.value.id&&!form.value.password){formError.value='新用户必须设置初始密码';return}if(resource.value==='users'&&!form.value.scopes?.length){formError.value='请为用户添加至少一个岗位范围';return}busy.value=true;try{const body:Row={...form.value};delete body.id;for(const f of schema.value.fields){if(f.type==='password'&&!body[f.key])delete body[f.key];if(['keywords','negativeKeywords'].includes(f.key)&&typeof body[f.key]==='string')body[f.key]=body[f.key].split(/[,，]/).map((s:string)=>s.trim()).filter(Boolean)}if(form.value.id)await api.put(`/admin/${resource.value}/${form.value.id}`,body);else await api.post(`/admin/${resource.value}`,body);drawer.value=false;form.value={};ElMessage.success('配置已保存');load()}catch(e){formError.value=errorText(e);reauthRequired.value=e instanceof ApiError&&e.code==='FRESH_TOTP_REQUIRED'}finally{busy.value=false}}
async function remove(row:Row){try{await ElMessageBox.confirm(`确认停用或移除“${row.name||row.code||row.account}”？历史引用由服务端保留。`,'确认变更',{type:'warning',confirmButtonText:'确认',cancelButtonText:'返回'});await api.delete(`/admin/${resource.value}/${row.id}`,{version:row.version});ElMessage.success('操作已完成');load()}catch(e){if(e!=='cancel'&&e!=='close')operationError.value=errorText(e)}}
watch(resource,()=>{page.value=1;keyword.value='';items.value=[];drawer.value=false;form.value={};operationError.value='';load()});onMounted(()=>{load();if(auth.me?.role==='ADMIN')options()})
</script>
<template><section class="page-heading"><div><p class="eyebrow">SYSTEM ADMINISTRATION</p><h1>{{ schema?.title||'管理配置' }}</h1><p class="muted">{{ schema?.subtitle }}</p></div><el-button v-if="!readOnly&&schema&&auth.me?.role==='ADMIN'" type="primary" @click="edit()">＋ 新增{{ schema.title.replace('管理','') }}</el-button></section><el-alert v-if="operationError" :title="operationError" type="error" :closable="false"/><section class="panel"><form class="filter-bar" @submit.prevent="page=1;load()"><el-input v-model="keyword" clearable placeholder="搜索名称 / 编码" aria-label="搜索管理记录"/><el-button type="primary" plain native-type="submit">查询</el-button><span class="muted">共 {{ total }} 条记录</span></form><PageState :loading="loading" :error="error" :empty="!items.length" @retry="load"><div class="table-scroll"><el-table :data="items" row-key="id"><el-table-column v-for="c in columns" :key="c.key" :label="c.label" min-width="150"><template #default="{row}"><span v-if="c.key==='createdAt'">{{ date(row[c.key]) }}</span><span v-else-if="['enabled','mustChangePassword'].includes(c.key)" class="status" :class="{completed:row[c.key]}">{{ row[c.key]?'是':'否' }}</span><span v-else>{{ display(row[c.key]) }}</span></template></el-table-column><el-table-column v-if="!readOnly" label="操作" width="150" fixed="right"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">停用/移除</el-button></template></el-table-column></el-table></div></PageState><div class="pagination"><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="load"/></div></section><el-drawer v-model="drawer" :title="(form.id?'编辑':'新增')+(schema?.title||'记录')" size="640px" :close-on-click-modal="false" @closed="form={};clearReauth()"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><div v-if="reauthRequired" class="fresh-totp"><p>请输入验证器中的六位动态验证码，验证后可继续保存。</p><label for="admin-fresh-totp">动态验证码</label><el-input id="admin-fresh-totp" v-model="reauthCode" maxlength="6" inputmode="numeric" autocomplete="one-time-code" @keyup.enter="reauthenticate"/><el-alert v-if="reauthError" :title="reauthError" type="error" :closable="false"/><el-button type="primary" :loading="reauthBusy" @click="reauthenticate">验证并返回</el-button></div><el-form v-if="drawer&&schema" label-position="top" @submit.prevent="save"><el-form-item v-for="f in schema.fields" :key="f.key" :label="f.label" :required="f.required"><el-switch v-if="f.type==='boolean'" v-model="form[f.key]"/><el-input-number v-else-if="f.type==='number'" v-model="form[f.key]" :min="0" :max="10000"/><el-select v-else-if="f.type==='select'" v-model="form[f.key]"><el-option v-for="(label,value) in f.options" :key="value" :label="label" :value="value"/></el-select><el-select v-else-if="f.type==='company'" v-model="form[f.key]" filterable clearable><el-option v-for="c in companies" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-select v-else-if="f.type==='department'" v-model="form[f.key]" filterable clearable><el-option v-for="d in departments" :key="d.id" :label="`${d.companyName||d.companyId} / ${d.name}`" :value="d.id"/></el-select><el-input v-else-if="f.type==='textarea'" v-model="form[f.key]" type="textarea" :rows="3"/><el-input v-else v-model="form[f.key]" :type="f.type==='password'?'password':'text'" :show-password="f.type==='password'" :autocomplete="f.type==='password'?'new-password':'off'"/></el-form-item><template v-if="resource==='users'"><h2>岗位与组织范围</h2><p class="muted">各岗位分别授权，切换时重新加载工作空间。</p><article v-for="(s,i) in form.scopes" :key="i" class="scope-editor"><el-form-item label="角色"><el-select v-model="s.role"><el-option v-for="(label,value) in roles" :key="value" :label="label" :value="value"/></el-select></el-form-item><el-form-item label="公司"><el-select v-model="s.companyId"><el-option v-for="c in companies" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="部门"><el-select v-model="s.deptId" clearable><el-option v-for="d in departments.filter(d=>d.companyId===s.companyId)" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item><el-button text type="danger" @click="form.scopes.splice(i,1)">移除此岗位</el-button></article><el-button @click="addScope">＋ 添加岗位</el-button></template><div class="form-footer"><el-button @click="drawer=false">返回</el-button><el-button type="primary" native-type="submit" :loading="busy" :disabled="reauthRequired||reauthBusy">保存配置</el-button></div></el-form></el-drawer></template>

<style scoped>
.fresh-totp{margin:16px 0;padding:16px;border:1px solid #d8e3ef;border-radius:8px;background:#f5f8fc}.fresh-totp label{display:block;margin-bottom:8px}.fresh-totp .el-input{max-width:240px;margin-right:12px}.fresh-totp .el-alert{margin:10px 0}.fresh-totp .el-button{margin-top:10px}
</style>
